    ["不客气，西奥多，我们是朋友！"] = "Пожалуйста, Теодор, мы друзья!",
    ["不接受这个结局"] = "Не принимайте эту концовку",
    ["不是我们镇上的……但他懂我们的痛。他说他见过很多可怜的人，在一场很远很远的战争里。"] = "Не из нашего города... но он понимает нашу боль. Он сказал, что видел много бедных людей на войне далеко-далеко.",
    ["不是这本书……那力量来源是什么？"] = "Не эта книга... Тогда откуда исходит эта сила?",
    ["不是，我只是……只是想在他得到永暗蜡烛的垂怜前跟他说几句话。"] = "Нет, я просто... Я просто хотел сказать ему несколько слов, прежде чем он получит милость Свечи Вечной Тьмы.",
    ["不止芬恩，而是<P_Yellow>在场所有的人</>。"] = "Не только Финн, но и все <P_Yellow> представляют </>.",
    ["不用了，替我回绝母亲已经是最大的回报。"] = "В этом не будет необходимости. Отказать маме за меня – это уже величайшая награда.",
    ["不知能否再次邀您用餐，让我表达歉意？"] = "Не согласитесь ли вы пообедать со мной еще раз, чтобы я мог выразить свои извинения?",
    ["不知道您是否愿意，和我——"] = "Я не знаю, согласишься ли ты, со мной…",
    ["不知道，我又没有恋人……这和这件事有关系吗？"] = "Не знаю, у меня нет любовника... это как-то связано с этим?",
    ["不行，要振作！一直忙着找治疗莎莉的方法，现在必须整理一下了。"] = "Нет, я должен взять себя в руки! Я был занят поисками способа исцелить Салли, и теперь мне нужно все организовать.",
    ["不要，迪文娜学姐！"] = "Нет, Старшая Дивина!",
    ["不错。先闻闻<P_Yellow>“绿色心情”</>，这能让你知晓第一轮比赛题目。"] = "Неплохо. Сначала понюхайте <P_Yellow> «Зеленое настроение» </>, это позволит вам узнать тему первого тура.",
    ["不错的选择，在做好之前，您可以先试试我们工坊的存货，请跟我来。"] = "Хороший выбор. Прежде чем он будет готов, вы можете сначала попробовать ассортимент нашей мастерской. Пожалуйста, пойдем со мной.",
    ["不需要，不喜欢？这都是你们自己买的呀！"] = "Не нужно, не нравится? Вы купили их сами!",
    ["不，我们只是用火祛除她身上的邪异。"] = "Нет, мы просто используем огонь, чтобы изгнать из нее зло.",
    ["不，是祂。祂告诉我，这样能控制顾客的欲望。"] = "Нет, это был Он. Он сказал мне, что это может контролировать желания клиентов.",
    ["为了在春天重逢……这不是很会说话吗？"] = "Чтобы снова встретиться весной... он неплохо владеет словами, не так ли?",
    ["为什么呢？变化是什么？"] = "Почему? В чем заключается изменение?",
    ["为什么是“二号”？"] = "Почему это «номер два»?",
    ["为什么？"] = "Почему?",
    ["为知识奔走的旅人，旷野点燃的孤灯，风的方向答案飘扬……"] = "Путешественник, бегущий за знаниями, одинокий светильник, зажженный в пустыне, ответ, летящий по направлению ветра...",
    ["主教说最真切的安眠是死亡，死亡会解决一切痛苦……"] = "Епископ сказал, что самый настоящий сон — это смерть, а смерть устранит всю боль…",
    ["主教说死亡是永远的安宁……可他没告诉我们，用这种方式死的人，连安宁的门都进不去。"] = "Епископ сказал, что смерть – это вечный мир... но он не сказал нам, что люди, умирающие таким образом, не могут даже войти в дверь мира.",
    ["丽贝卡，我和莱西亚组队。"] = "Ребекка, я объединяюсь с Лесией.",
    ["举手之劳"] = "Небольшая услуга",
    ["之前的自杀者都是拉姆德小镇周边的居民，亚瑟是从廷根来的，特意来拉姆德……自杀。"] = "Все прежние самоубийцы были жителями городка Ламуд и его окрестностей. Артур же приехал из Тингена... нарочно в Ламуд, чтобы покончить с собой.",
    ["也不是没可能。"] = "Это не исключено.",
    ["也没错，大厅里这艘的确只是它的模型。"] = "Верно, то, что стоит в зале — всего лишь её модель.",
    ["也许，某种意义上，你的出现，也算是克莱恩寄出的一封信。"] = "Возможно, в каком-то смысле ваше появление можно расценить как письмо, отправленное Кляйном.",
    ["书上是这么写的，我们至少得试试！"] = "Так написано в книге, надо хотя бы попробовать!",
    ["书籍"] = "Книги",
    ["书里是这么写的，不信你自己看。"] = "Так написано в книге, если не верите, посмотрите сами.",
    ["事件根源"] = "Основная причина инцидента",
    ["亚瑟的委托实际上并没有结束，出于值夜者的使命，我也会调查到底的。"] = "Комиссия Артура на самом деле еще не закончилась. В силу своего долга Ночного Ястреба я тоже проведу расследование до конца.",
    ["亚瑟，你的妻子委托我来找你。"] = "Артур, твоя жена поручила мне найти тебя.",
    ["亢奋的村民们紧紧拉住你的手，热情地把你带入舞蹈中。"] = "Взволнованные жители деревни крепко держали вас за руки и с энтузиазмом вовлекали в танец.",
    ["交出“心脏”"] = "Сдать «сердце»",
    ["交给伊琳处理"] = "Предоставьте это Ирен.",
    ["交给我吧"] = "Оставь это мне",
    ["人倒霉起来真倒霉……不知怎么的，就想起了死。"] = "Так не повезло людям, что им не везет... Не знаю почему, но я думаю о смерти.",
    ["人群中响起窸窸窣窣的讨论声，学员们从四周渐渐聚到了台前。"] = "В толпе послышался шорох дискуссий, и студенты со всей округи постепенно собрались перед сценой.",
    ["什、什么？我还没说。"] = "Ч-что? Я не закончил.",
    ["什么你的梦境？这是我的梦境！"] = "Что значит твоя мечта? Это моя мечта!",
    ["什么叫找到更好的结婚对象？"] = "Что вы подразумеваете под поиском лучшего кандидата на брак?",
    ["什么掉下来了，这是……莎莉刚才写的东西？"] = "Что упало? Это... что-то, что Салли только что написала?",
    ["什么？！音乐声太大，我听不见。不要浪费时间说话了，来加入我们吧。"] = "Что? ! Музыка была слишком громкой, и я ее не слышал. Не тратьте время на разговоры, приходите к нам.",
    ["今天也没发现正规且有效的仪式魔法……"] = "Сегодня до сих пор не найдено формальной и эффективной Ритуальной Магии...",
    ["今天是个特殊的日子，永暗蜡烛允诺你们永恒的安宁。"] = "Сегодня особенный день; Свеча Вечной Тьмы обещает вам вечный покой.",
    ["今天是他的大日子，他会获得永暗蜡烛的垂怜！肯定在哪准备呢！"] = "Сегодня его великий день: он удостоится милости Свечи Вечной Тьмы! Наверняка готовится где-то неподалеку!",
    ["今天的工作顺利吗？"] = "Работа сегодня прошла хорошо?",
    ["今晚？他们的庆典都是为了庆祝有人成功自杀，但老罗德已经被救下了……"] = "Сегодня вечером? Все их праздники посвящены тому, чтобы кто-то успешно совершил самоубийство, но Старый Род уже спасен...",
    ["仔细想想，布兰登教你们力量时，还有什么不寻常的？"] = "Вспомни хорошенько: когда Брэндон обучал вас силе, было ли что-то необычное?",
    ["他一直在试图找回她，花费无数时间金钱，也要找回那位……名叫莎莉丝特的小姐。"] = "Он упорно пытается ее найти, тратя уйму времени и денег, лишь бы отыскать ту самую... юную леди по имени Селеста.",
    ["他临死前，还给我留了五大箱蜡烛，够我用一辈子……我想大家再用一次，维斯塔工坊的蜡烛，明亮温暖的蜡烛。"] = "Перед смертью он оставил мне пять больших ящиков свечей — хватит на всю жизнь... Мне так хочется, чтобы все снова зажгли свечи мастерской Весты, эти яркие, теплые свечи.",
    ["他也像个老师了啊。也对，他如果没有成为黑荆棘的员工，也会是个很好的老师。"] = "Он тоже стал похож на учителя. Правильно, если бы он не стал сотрудником «Чёрного Терновника», он был бы отличным учителем.",
    ["他们疯了。"] = "Они сумасшедшие.",
    ["他们的舞蹈带来了冥河的声音，我想起了一件很重要的事。"] = "Их танец доносил шум Реки Смерти, и я вспомнил кое-что очень важное.",
    ["他刚才说，十三只……"] = "Он только что сказал, что тринадцать...",
    ["他想献祭所有人？！"] = "Он хочет принести в жертву всех?!",
    ["他是我的学生，也不止是学生。你认识克莱恩？"] = "Он был моим учеником, и больше, чем просто учеником. Ты знаешь Клейна?",
    ["他没来……丽贝卡，我和米贝拉一组。"] = "Он не пришел... Ребекка, я в группе с Мибеллой.",
    ["他用“火种”窃取了一件物品里的污染。"] = "Он с помощью \"Растопки\" похитил осквернение из одного предмета.",
    ["他积攒自己的鲜血，尝试启动生命炼成和复活仪式，却也因此失控，变成了怪物。"] = "Он накопил собственную кровь, пытаясь инициировать ритуал трансмутации и воскрешения жизни, но из-за этого потерял контроль и превратился в монстра.",
    ["他被严重污染了，很快就会变成恶魔。"] = "Он сильно испорчен и вскоре превратится в демона.",
    ["他让我把名字写在新黑板上——这算不寻常吗？"] = "Он попросил меня написать свое имя на новой доске — это считается необычным?",
    ["他说他帮那些士兵写了回家的信……他一边说，一边发抖，比我们还痛苦。"] = "Он сказал, что помогал этим солдатам писать письма домой... Он дрожал, когда говорил, ему было еще больнее, чем нам.",
    ["他还没变成怪物……还有救，对吗？"] = "Он еще не превратился в монстра... надежда еще есть, правда?",
    ["他还活着！只是晕过去了？"] = "Он все еще жив! Просто потерял сознание?",
    ["他，想逃避死亡。"] = "Он хочет избежать смерти.",
    ["以前邓恩队长说过，很多年前，一场疾病夺走了老尼尔即将订婚的恋人。"] = "Капитан Данн однажды рассказал, что много лет назад болезнь унесла невесту Старины Нила, на которой он собирался жениться.",
    ["伊琳……"] = "Айрин...",
    ["伊琳？！"] = "Ирен?!",
    ["休息室中央的钢琴流淌出动人的音乐，吧台和座椅附近学员们互相碰杯，窗外，灵界光影流动。\n你静静地注视着这些事物。"] = "Из центра гостиной лились чарующие звуки фортепиано, ученики у стойки и столиков весело звенели бокалами, а за окном медленно переливались загадочные тени и всполохи мира духов.\nВы молча наблюдаете за происходящим.",
    ["会的，我相信那些明亮、温暖的东西会一直存在。"] = "Это будет. Я верю, что эти яркие и теплые вещи будут существовать всегда.",
    ["会说话、长眼睛的箱子？"] = "Коробка, которая умеет говорить и имеет глаза?",
    ["但……帕里克，你没有报名？而且你中途离开过学派吗？"] = "Но... Парик, ты не подписался? И ты ушел из школы на полпути?",
    ["但不止这样，还有——"] = "Но дело не только в этом, есть еще…",
    ["但他想用这个仪式和永暗蜡烛做什么呢？"] = "Но что он хочет делать с этим ритуалом и Свечей Вечной Тьмы?",
    ["但客人们失去的美好时光无法弥补，比如被您打断的求婚。"] = "Но прекрасное время, потерянное гостями, невозможно восполнить, как, например, прерванное вами предложение.",
    ["但我们死后才发现，正常死去的人，灵魂会顺着冥河往下漂，漂到属于他们的安息之地。"] = "Но только после того, как мы умрем, мы обнаружим, что души людей, умерших обычной смертью, плывут по реке Стикс к месту своего упокоения.",
    ["但我更怕活着……每次闭上眼睛，我就看到那些被我杀死的敌人……他们问我，为什么你还活着……"] = "Но еще больше я боюсь жить... Каждый раз, когда я закрываю глаза, я вижу тех врагов, которых я убила... Они спрашивают меня, почему ты еще жив...",
    ["但这些症状很快就消失了，而菲丽丝却陷入沉睡。"] = "Но эти симптомы быстро исчезли, а Филлис погрузилась в глубокий сон.",
    ["佐伊学姐，我可以证明，“心脏”是我们组队捕获的。"] = "Старшая Зоя, я могу доказать, что «сердце» было захвачено нашей командой.",
    ["佐伊学姐，这是污蔑，这颗“心脏”是我自己的！"] = "Старшая Зоя, это клевета, это «сердце» мое!",
    ["作为击弦乐器，钢琴最重要的部分，就是琴弦。"] = "Как ударный инструмент, самой важной частью фортепиано являются его струны.",
    ["你一定会成功的"] = "У тебя обязательно получится",
    ["你为什么不跳舞？"] = "Почему ты не танцуешь?",
    ["你们不要误导我的弟弟。我的父母已经得到了永恒的宁静与幸福。"] = "Не вводи в заблуждение моего младшего брата. Мои родители уже обрели вечный покой и счастье.",
    ["你们将进入其中，通过调查和推理，找出关键线索。"] = "Вы войдете внутрь и путем расследования и логических умозаключений найдете ключевые улики.",
    ["你们是警察？好……一定要治好菲丽丝！"] = "Вы полицейский? Хорошо... ты должен вылечить Филлис!",
    ["你们要和我一起，参与“启明小队”的调查。"] = "Вы присоединитесь ко мне и примете участие в расследовании «Отряда Рассвета».",
    ["你们要烧死菲丽丝？！给我住手！"] = "Ты собираешься сжечь Филлис заживо?! Прекрати!",
    ["你们错了，死亡是寂静，一切都消失了。"] = "Вы ошибаетесь. Смерть — это безмолвие, где исчезает всё.",
    ["你会演戏？"] = "Ты можешь действовать?",
    ["你先带上它，我以后再和你讲“破晓号”的故事。"] = "Ты сначала возьми, а я потом расскажу тебе историю «Зари».",
    ["你刚才在想什么？怎么叫也叫不醒？"] = "О чем ты сейчас думал? Я не мог тебя разбудить, как бы я ни звонил.",
    ["你刚才说，我们都看到了那场婚礼？！"] = "Ты только что сказал, что мы оба видели ту свадьбу?!",
    ["你叔叔出事了！"] = "Что-то случилось с твоим дядей!",
    ["你和蒙特利不一样"] = "Ты отличаешься от Монтерея",
    ["你好，蒙特利"] = "Привет, Монтерей",
    ["你妻子说你不会丢下他们，对了，她还为你痛骂了你的老板。"] = "Твоя жена сказала, что ты не бросишь их. Кстати, она тоже от вашего имени прокляла вашего босса.",
    ["你当然可以难过，死亡是悲伤的。"] = "Ты, конечно, можешь горевать. Смерть всегда печальна.",
    ["你怎么知道……菲丽丝告诉你的？"] = "Откуда ты узнал... Филлис рассказала тебе?",
    ["你总是那么敏锐，你是我们三个人中最聪明的。"] = "Ты всегда такой сообразительный, ты самый умный из нас троих.",
    ["你想了解菲丽丝的情况，就去赢得比赛，加入启明小队。    "] = "Если хочешь понять ситуацию Филлис, выиграй соревнование и присоединись к Отряду Рассвета.",
    ["你或许听说过老尼尔？他以前负责看守材料、武器和文献库，需要经常采购。"] = "Возможно, вы слышали о Старом Ниле? Раньше он отвечал за охрану материалов, оружия и архивов, и ему приходилось часто делать покупки.",
    ["你是他的谁？维斯塔把工坊的欠款都还了吧，芬恩都要自杀了，你们就别找麻烦了。"] = "Кто ты для него? Vista уже погасила долги мастерской. Финн собирается покончить жизнь самоубийством, так что не доставляйте ему неприятностей.",
    ["你是老罗德先生的什么人？"] = "Кто ты для мистера Роуда?",
    ["你有没有想过，沉睡症有多种原因，菲丽丝是哪一种？"] = "Вы когда-нибудь задумывались, что существует множество причин сонной болезни, и какая из них – Филлис?",
    ["你来过这里？"] = "Вы бывали здесь раньше?",
    ["你来，这里多了新的<P_Yellow>遗书</>，可能是为庆典准备的。"] = "Идите сюда, здесь новые предсмертные записки <P_Yellow> </>. Возможно, они готовятся к празднованию.",
    ["你查到什么了吗？后来那六个自杀者是谁救下的？"] = "Вы нашли что-нибудь? Кто впоследствии спас шестерых самоубийц?",
    ["你真的没事吗？有没有哪里不舒服？"] = "Ты действительно в порядке? Есть ли место, где вы чувствуете себя некомфортно?",
    ["你知道我的名字，你认识我？"] = "Ты знаешь мое имя? Ты меня знаешь?",
