    ["怎么还有一张纸？"] = "Зачем еще один листок бумаги?",
    ["思考"] = "Думать",
    ["总之……很抱歉，错了就是错了。钢琴已经损坏，我会向上级申请赔偿，无需麻烦您。"] = "Как бы то ни было... прошу прощения, ошибка есть ошибка. Фортепиано повреждено, я запрошу компенсацию у руководства, вам не о чем беспокоиться.",
    ["总是由你邀请我，会显得我缺乏主动性。"] = "Это ты всегда меня приглашаешь, из-за чего мне кажется, что мне не хватает инициативы.",
    ["总结"] = "Краткое содержание",
    ["恭喜回神！弗莱告诉我，你是来喝咖啡的，我已经准备好了，走吧。"] = "Поздравляю с возвращением в чувство! Фрай сказал мне, что ты пришел выпить кофе; Я уже приготовила, поехали.",
    ["您……您是蜡烛的主人？"] = "Вы... вы хозяин свечи?",
    ["您也知道了啊，自杀的事传得好快。"] = "Вы тоже уже знаете? Вести о самоубийствах разносятся так быстро.",
    ["您使用的纸张是警局专用纸，音符形状别扭，乐谱格式奇特，就像一份报告书？"] = "Бумага, которую вы использовали, — официальная бумага полицейского участка, записи имеют неуклюжую форму, а музыкальный формат странный — похоже на отчет?",
    ["您好，佐伊学姐。"] = "Здравствуйте, Старшая Зоя.",
    ["您好，您看见芬恩了吗？"] = "Привет, ты видел Финна?",
    ["您好，请问您看到芬恩了吗？"] = "Здравствуйте, могу я спросить, видели ли вы Финна?",
    ["您愿意和一个惯性迟到的人见第三次吗？"] = "Хотели бы вы познакомиться с человеком, который хронически опаздывает на третью встречу?",
    ["您拒绝是应该的，毕竟我不是什么有趣的人。"] = "Вам следует отказаться. Ведь я не интересный человек.",
    ["您是……托马斯神父？"] = "Вы... Отец Томас?",
    ["您是初代拉姆德男爵？！"] = "Ты первый барон Ламуд?!",
    ["您竟然愿意见他第二次！"] = "Подумать только, вы действительно согласились бы увидеть его во второй раз!",
    ["您耳朵红了。"] = "У тебя красные уши.",
    ["惨叫"] = "Крик",
    ["想不到小芬恩还有朋友呢，我以为他只会淌眼泪，除了维斯塔，没人喜欢他呢。"] = "Я не думал, что у маленького Финна есть друзья. Я думал, он умеет только плакать; кроме Висты он никому не нравился.",
    ["想起一些事情，还是当面交代比较好。"] = "Некоторые вещи запомнил, лучше объяснить при личной встрече.",
    ["感谢你没有泼我咖啡，罗珊。"] = "Спасибо, что не выплеснула на меня кофе, Розанна.",
    ["感谢你的热心，那就交给你了。"] = "Спасибо за ваш энтузиазм, тогда я оставлю это вам.",
    ["成交！"] = "Иметь дело!",
    ["成功了！呼，我真的不擅长慢节奏的歌。"] = "Успех! Уф, я действительно не очень хорош в медленных песнях.",
    ["我……"] = "Я...",
    ["我……好像做了一个梦，在梦里见证了尼尔先生与莎莉丝特小姐的过往。"] = "Я... кажется, мне приснился сон, и во сне я стал свидетелем прошлого мистера Нила и мисс Селесты.",
    ["我、我不知道……"] = "Я, я не знаю...",
    ["我、我是来道别的。"] = "Я, я пришел попрощаться.",
    ["我不是文职人员，我应该算是……值夜者？"] = "Я не гражданский служащий. Пожалуй, меня можно считать... Ночным Ястребом?",
    ["我不死，你们死！"] = "Я не умру, ты умрешь!",
    ["我不能死……死太可怕了……我在战场上见到那么多死人，死得都很残忍……"] = "Я не могу умереть... смерть слишком страшна... Я видел столько мертвецов на поле боя, все они погибли так жестоко...",
    ["我九年没买过香水了，我从来不需要它！"] = "Я уже девять лет не покупаю духи, они мне никогда не нужны!",
    ["我也想见证那场，没能举办的婚礼……"] = "Я также хочу стать свидетелем той свадьбы, которой так и не произошло...",
    ["我以为这只是小孩一时的爱好，可他哪怕摔破了腿，磕伤了脑袋，依旧不放弃练习。"] = "Я думал, что это просто мимолетное увлечение ребенка, но даже когда он сломал ногу или ушиб голову, он никогда не бросал занятия.",
    ["我们会把这些明亮的东西储存在记忆里，形成我们人性的基石。"] = "Мы сохраним эти яркие вещи в своей памяти, образуя краеугольный камень нашей человечности.",
    ["我们会继续调查，菲丽丝交给我们吧。"] = "Мы продолжим расследование, оставьте Филлис нам.",
    ["我们先去找亚瑟。"] = "Давай сначала найдём Артура.",
    ["我们几个是朋友，都有些心理上的……困扰。"] = "Мы друзья, и у всех есть какие-то психологические... проблемы.",
    ["我们单独都解决不了它……我同意你的建议。"] = "Поодиночке никому из нас с ним не справиться... Я согласен с твоим предложением.",
    ["我们原本的症状被治愈，却都染上<P_Yellow>更邪异的病症</>……"] = "Наши первоначальные симптомы были излечены, но мы все заразились <P_Yellow>более злыми симптомами</>...",
    ["我们想，既然这么厉害的人都在用这根蜡烛……那一定就是对的。"] = "Мы подумали, что раз такой могущественный человек использует эту свечу... значит, это правильно.",
    ["我们还一起战斗过，算是朋友？"] = "Мы тоже сражались вместе, это считается друзьями?",
    ["我们都会受到惩罚的！我们都会死！我们都会死！"] = "Мы все будем наказаны! Мы все умрем! Мы все умрем!",
    ["我们都可以向永暗蜡烛祈求吗？"] = "Мы все можем возносить молитвы Свече Вечной Тьмы?",
    ["我会修好琴弦，让音乐再度响起，这样才能平息他们的愤怒。"] = "Я починю струны и позволю музыке снова зазвучать; только тогда их гнев может быть утолен.",
    ["我会好好珍藏。"] = "Я буду бережно хранить это.",
    ["我会好好记得的。再见，阿兹克先生！"] = "Я непременно всё запомню. До свидания, господин Азик!",
    ["我会把他逮捕回警局，请各位继续用餐！"] = "Я арестую его и отвезу в участок. Пожалуйста, продолжайте есть!",
    ["我做了一个梦……"] = "У меня была мечта...",
    ["我儿子也上过战场，他说，蜡烛的使命就是被点燃。"] = "Мой сын тоже отправился на поле боя; он сказал, что миссия свечи – зажечься.",
    ["我只是偷两具尸体卖给诊所，这是造福医学发展啊！"] = "Я как раз украл два трупа, чтобы продать их в клинику; это во благо прогресса медицины!",
    ["我叫{{PlayerName}} ，克莱恩·莫雷蒂先生指引过我。"] = "Меня зовут {{PlayerName}}, меня направлял господин Клейн Моретти.",
    ["我叫芬恩，是……以前是蜡烛工坊的学徒。"] = "Меня зовут Финн, я... раньше был учеником в свечной мастерской.",
    ["我可以和您一起调查。"] = "Я могу провести расследование вместе с вами.",
    ["我可以看看这些书吗？"] = "Могу ли я посмотреть эти книги?",
    ["我可以证明，“门”没有启用过，帕里克一直在学派内。"] = "Я могу доказать, что «Дверь» никогда не активировалась; Парик все время был в школе.",
    ["我向女神起誓，我会逮捕凶手！"] = "Клянусь Богиней, я схвачу убийцу!",
    ["我和帕里克一起，捕获了梦境捕手的心脏。"] = "Мы с Париком вместе покорили сердце Ловец снов.",
    ["我和洛耀会先去调查工厂和他们的住所，辛苦你去<P_Yellow>拉姆德小镇</>寻回亚瑟。"] = "Ло Яо и я сначала отправимся исследовать фабрику и их дома. Мне придется побеспокоить вас, чтобы вы отправились в <P_Yellow>Ламуд Small Town</> и забрали Артура.",
    ["我和瑞科的约会被破坏，难道是我们的错？！"] = "Мое свидание с Рико было испорчено – это наша вина?!",
    ["我喜欢自己行动……就算赢了，他们也会怀疑我作弊。"] = "Мне нравится действовать самостоятельно... даже если я выиграю, они заподозрят, что я жульничаю.",
    ["我在。"] = "Я здесь.",
    ["我在听。"] = "Я слушаю.",
    ["我在想……西奥多抓老鼠干什么？"] = "Мне интересно... для чего Теодор ловит мышей?",
    ["我在这里长大，留下很多记忆。"] = "Я вырос здесь и оставил много воспоминаний.",
    ["我帮您解决闹剧，修好钢琴。作为回报，请您回去告诉我母亲，您对我不感兴趣。"] = "Я помогу тебе разрешить этот фарс и починить пианино. Взамен, пожалуйста, вернись и скажи моей матери, что я тебе не интересен.",
    ["我很好，布兰登先生会为我高兴的。"] = "Со мной всё в порядке, мистер Брэндон порадуется за меня.",
    ["我很好，还新学了几句玩笑。"] = "Со мной все в порядке, я даже выучил несколько новых шуток.",
    ["我很清醒，我想清楚了。我已经很老了，病得连羊都喂不了。如果没有我，我的孩子能多吃一个面包。"] = "У меня очень ясная голова, и я все обдумал. Я уже очень стар и настолько болен, что не могу даже кормить овец. Если бы меня не было, мои дети могли бы съесть еще один кусок хлеба.",
    ["我得先把这些涂鸦清理掉——当然，如果你愿意帮我的话，现在就可以拿去。"] = "Сначала мне нужно убрать эти граффити — конечно, если вы готовы мне помочь, вы можете забрать их сейчас.",
    ["我得知您喜欢音乐，尤其是这首钢琴曲，所以趁值班间隙，抄下了这份琴谱，希望能证明我并非蔑视艺术的人。"] = "Я узнал, что ты любишь музыку, особенно эту пьесу для фортепиано, поэтому во время перерыва в смену переписал эти ноты, надеясь доказать, что я не из тех, кто презирает искусство.",
    ["我必须找回力量，让大家永远爱上香水。"] = "Я должен вернуть себе силу заставить всех полюбить этот аромат навсегда.",
    ["我怀疑这些蜡烛，是某个<P_Yellow>神奇物品的分身</>，它能放大人对死亡的渴望。"] = "Я подозреваю, что эти свечи — воплощение некоего <P_Yellow>мистического предмета</>, способного разжигать в людях тягу к смерти.",
    ["我总觉得，亲人的死亡就像步入冬天，带来连绵的寒冷。"] = "Я всегда чувствую, что смерть близкого человека подобна вступлению в зиму, приносящую затяжной холод.",
    ["我想也是，所以才回来找你们商量一下。"] = "Я тоже так думаю, поэтому вернулся, чтобы обсудить это с вами.",
    ["我想再去查查镍币书店，找找布兰登。"] = "Я хочу еще раз проверить книжный магазин «Никель» и поискать Брэндона.",
    ["我想找这里的学徒，芬恩。您认识他吗？"] = "Я ищу здесь ученика, Финн. Вы его знаете?",
    ["我想谢谢您和阿兹克先生救了老罗德。医生帮老罗德处理了伤口，但他昨天夜里做了很多噩梦。"] = "Я хочу поблагодарить вас и мистера Азика за спасение Старого Рода. Доктор обработал его раны, но прошлой ночью ему снилось много кошмаров.",
    ["我想起了我的孩子。"] = "Я вспомнила своего ребенка.",
    ["我想陪他，但我说不出什么安慰的话……"] = "Я хочу составить ему компанию, но не знаю, какие слова утешения сказать...",
    ["我想，我很期待和您在不同的地方见面，谈论音乐、书籍、或者其他。"] = "Думаю, я с нетерпением жду встречи с вами в разных местах, чтобы поговорить о музыке, книгах или других вещах.",
    ["我慷慨送你猎人的火焰烤一<P_Yellow>烤</>！"] = "Я щедро подарю тебе пламя Охотника <P_Yellow>roast</>!",
    ["我担心是我造成了这场灾难，我想要阻止它。"] = "Меня беспокоит, что я стал причиной этой катастрофы, и я хочу ее остановить.",
    ["我揣在身上，越来越冷，越来越觉得活着没意思……我们这样的人，哪个没想过死呢……"] = "Я держал это при себе, и мне становилось всё холоднее и холоднее, всё сильнее казалось, что жить нет никакого смысла... Кто из таких, как мы, не думал о смерти...",
    ["我救了人，永暗蜡烛缺少了足够的亡魂……"] = "Я спасал людей, поэтому Свече Вечной Тьмы не хватает душ...",
    ["我救了其中六个人，但不找到幕后之人，受害者还会增加。"] = "Я спас шестерых из них, но если мы не найдем человека, стоящего за этим, число жертв увеличится.",
    ["我无法抗拒嗜血冲动，忍不住到处咬鸭脖子。"] = "Я не могу сопротивляться жажде крови и не могу не кусать утиные шеи повсюду.",
    ["我明白了，变化是阿兹克先生您救下的那六个自杀者！"] = "Я понимаю, разница в шести жертвах самоубийства, которых вы спасли, господин Азик!",
    ["我明白了，还有其他信息吗？"] = "Я так понимаю, есть еще какая-то информация?",
    ["我是一名警察，官方的猎犬，你不能和我说话。"] = "Я полицейский, государственная ищейка. Тебе нельзя со мной разговаривать.",
    ["我是说，什么都好，只要能和您一起。"] = "Я имею в виду, все в порядке, пока оно с тобой.",
    ["我是负责这起案件的警察。发生这种事，我真的很抱歉。"] = "Я полицейский, ведущий это дело. Мне искренне жаль, что это произошло.",
    ["我曾经也是一个老师，一位父亲。我想，我能体会维斯塔的心情。"] = "Когда-то я был учителем, отцом. Думаю, я могу понять, что чувствовала Vista.",
    ["我来换班了，你说呢？手上拿的什么？"] = "Я здесь, чтобы возглавить смену, что скажешь? Что ты держишь в руке?",
    ["我来负责揭晓第二届“破晓之时”第一轮比赛的命题——"] = "На мне лежит ответственность за раскрытие темы первого тура 2-го «Часа рассвета» —",
    ["我爸爸妈妈上周……自杀了……呜呜……这是高兴的事……我不能哭……呜呜……可是我再也看不到他们了，我好难过……"] = "Мои папа с мамой на прошлой неделе... покончили с собой... у-у-у... Это же радостное событие... Мне нельзя плакать... у-у-у... Но я ведь больше никогда их не увижу, мне так тяжело...",
    ["我现在也是黑荆棘安保公司的职员。"] = "Сейчас я также являюсь сотрудником охранной компании «Чёрный Терновник».",
    ["我用序列四“不死者”的非凡特性制作了永暗蜡烛，只要不点燃蜡烛，蜡烛的主人就永远不会死亡。"] = "Я использовал характеристику Потусторонний из 4-й последовательности «Бессмертие», чтобы создать Свечу Вечной Тьмы; пока свеча не зажжена, ее владелец никогда не умрет.",
    ["我的火焰连查拉图的胡须都能炭<P_Yellow>烤</>！"] = "Моё пламя способно сжечь даже уголь-<P_Yellow>гриль</> бороду Заратула!",
    ["我的钢琴！就连因蒂斯的大炮都懂得避开钢琴！"] = "Моё фортепиано! Да даже интисские пушки знают, что в фортепиано стрелять нельзя!",
    ["我相信您"] = "Я верю в тебя",
    ["我相信您。"] = "Я верю вам.",
    ["我知道了，所以……你在庆典上分发的不是托马斯神父带来的蜡烛，而是<P_Yellow>维斯塔的手工蜡烛</>！"] = "Я понял, так что... то, что вы раздавали на празднике, было не свечой, которую принес отец Томас, а свечой ручной работы <P_Yellow> Vista </>!",
    ["我知道这很艰难，但请保重身体，我……随时都在。"] = "Я знаю, как это тяжело, но, пожалуйста, берегите себя. Я... всегда рядом.",
    ["我能不能约……"] = "Могу ли я спросить...",
    ["我能为他做点什么吗？"] = "Могу ли я что-то для него сделать?",
    ["我能拿到“心脏”，还得谢谢你的涂鸦和牛奶……"] = "Мне удалось получить «сердце», спасибо вашим каракулям и молоку...",
    ["我跟你不是同行，你是来参加庆典的?"] = "Мы с вами не коллеги. Вы пришли на праздник?",
    ["我通过梦境占卜，看见它被西奥多从书店偷走了。"] = "Через гадание во сне я увидела, что ее украл из книжного магазина Теодор.",
    ["我问他为什么要在十来岁的年纪就要做这样的选择。他回答我，因为我是他的偶像和榜样……"] = "Я спросил его, почему он хотел сделать такой выбор в возрасте десяти лет или около того. Он ответил мне, потому что я был его кумиром и примером для подражания...",
    ["我隐约记得，“永暗蜡烛”跟我有关系。但我不记得细节了……"] = "I vaguely remember that the \"Candle of Eternal Darkness\" has something to do with me. Но подробностей я не помню...",
    ["战术？像“愚者”先生用你的灵体之线拧麻<P_Yellow>花</>！"] = "Тактический? Например, как Мистер Шут скручивает нити вашего духовного тела <P_Yellow> в крендель</>!",
    ["所以你们按照书里的偏方，用火为菲丽丝驱邪？"] = "Итак, вы воспользовались народными средствами, описанными в книге, и использовали огонь, чтобы изгнать зло из Филлис?",
    ["所以你们被困在了这里？"] = "Так ты здесь в ловушке?",
    ["所以你偷走布兰登先生的书，想解决麻烦？"] = "Так вы украли книгу мистера Брэндона, чтобы решить проблему?",
    ["所以她从廷根回来，我们都想让她帮我们看病。"] = "Поэтому, когда она вернулась из Тингена, мы все хотели, чтобы она вылечила наши болезни.",
    ["所以托马斯的计划失败了，最终失控！"] = "Итак, план Томаса провалился, что привело к окончательной потере контроля!",
    ["所以蜡烛工坊是因为后继无人倒闭了吗？"] = "Значит, свечной цех закрылся, потому что не было преемника?",
    ["所以这里也有菲丽丝的记忆？可梦境空间这么大，怎么找？"] = "Значит, воспоминания Филлис тоже здесь? Но Пространство Мечты настолько огромно, как нам его найти?",
    ["手写的字？这是……笔记本？"] = "Рукописный текст? Это... блокнот?",
    ["手工制品，早该淘汰了。维斯塔把他送进了制糖厂当学徒，这样还能混口饭吃。"] = "Ручному труду давно пора на свалку истории. Веста пристроил его учеником на сахарный завод — так хоть на кусок хлеба заработает.",
    ["打开看看"] = "Открыть и посмотреть",
    ["打鼾"] = "Храп",
    ["扔进垃圾桶也正常……"] = "Если выбросили в мусорку — неудивительно...",
    ["托马斯神父值得怀疑，他在整个事件里出现得太巧合，过分热心。"] = "Отец Томас подозрителен; он появлялся слишком случайно на протяжении всего мероприятия и был слишком полон энтузиазма.",
    ["托马斯神父最初并不是帮忙找人，他是要把我引到古堡，寻找谁破坏了他的计划！这样就全解释得通了！"] = "Отец Томас поначалу не помогал искать людей; он хотел заманить меня в замок, чтобы узнать, кто рушит его планы! Это всё объясняет!",
    ["托马斯神父，您怎么来了这里？"] = "Отец Томас, почему вы здесь?",
    ["找回……病逝的，莎莉丝特……"] = "Найдите... умершую Селесту...",
    ["把木雕收进抽屉"] = "Положите резьбу по дереву в ящик.",
    ["把第一轮比赛捕获的“心脏”，喂给“织梦黑匣”吧！"] = "Скормите «сердце», добытое в первом раунде состязания, «Ткущему сны чёрному ящику»!",
    ["报名参赛"] = "Подать заявку на участие",
    ["抱歉。"] = "Прошу прощения.",
    ["抱歉用借口喊您过来，我怕别人听到。这件事只能告诉阿兹克先生和他信任的人……"] = "Извините, что воспользовался предлогом, чтобы позвонить вам; Я боялся, что другие услышат. Об этом можно рассказать только господину Азику и тем, кому он доверяет...",
    ["抱歉，我……"] = "Мне жаль, я...",
    ["抱歉，我上次临时被叫去蹲守逃犯，这次……"] = "Простите, меня вызвали в последнюю минуту, чтобы выследить беглеца, и на этот раз...",
    ["押韵炸了，这是战书！"] = "Рифма взрывная, это объявление войны!",
    ["拆穿蒙特利"] = "Разоблачить Монтерей",
    ["拉姆德小镇的牧师上报了此事。"] = "Священник городка Ламуд доложил об этом происшествии.",
    ["拦在伊琳身前"] = "Блок перед Ирен",
    ["拿去吧，我要给他记三次违规！"] = "Забирайте! Я запишу ему целых три нарушения!",
    ["接过资料"] = "Возьмите документы",
    ["攻击"] = "Атака",
    ["放下高傲的嘴<P_Yellow>角</>，小心你头顶长出触<P_Yellow>角</>。"] = "Опустите свои высокомерные <P_Yellow>lips</>, следите за тем, чтобы на вашей <P_Yellow>head</> не росли рога.",
    ["放心吧"] = "Не волнуйся",
    ["放着别动，我来收拾！"] = "Оставь это там, я уберу!",
    ["救命！我刚按顺序整理好单据！"] = "Помощь! Я только что закончила расставлять квитанции по порядку!",
    ["救菲丽丝？通过烧死她的方式？"] = "Спасти Филлис? Сжечь ее заживо?",
    ["教会活动上，主教送给我们蜡烛。那蜡烛不用点燃就能发光，惨白惨白的，省下一大笔蜡烛钱……可用久了，心里总是发冷。 "] = "На церковном мероприятии архиерей подарил нам свечи. Свечи светились, не зажигаясь, бледно-белые, экономя много денег на свечи... но после долгого их использования у меня всегда было холодно на сердце.",
    ["教会？"] = "Церковь?",
    ["文献库内储存着在他家发现的物品，一起看看吧。"] = "В архивах хранятся предметы, найденные у него дома. Давайте посмотрим вместе.",
    ["文职人员吗？还是？"] = "Вы канцелярский сотрудник? Или?",
    ["新坟里的都是穷鬼，失业的工人，被毒打的女仆，破产的老爷，没什么值钱陪葬。"] = "Новые могилы — это все бедняки, безработные, оскорбленные служанки, господа-банкроты; рядом с ними не закопано ничего ценного.",
    ["无"] = "Никто",
    ["既然他们的命这么轻……为什么不能换我的永生？我是在帮他们解脱！"] = "Раз уж их жизни ничего не стоят... почему бы не обменять их на мое бессмертие? Я же просто дарую им освобождение!",
    ["早安，莎莉丝特小姐，请不要调侃我。"] = "Доброе утро, мисс Селеста. Пожалуйста, не дразни меня.",
    ["明天你会来的，对吧？"] = "Ты ведь придешь завтра, правда?",
    ["明早校刊上头条：纵火家惨变哭包<P_Yellow>菜</>！"] = "Заголовок в завтрашней школьной газете: Поджигатель превращается в плаксу <P_Yellow>wimp</>!",
    ["春天？"] = "Весна?",
    ["昨天比赛睡太久，晚上失眠了。"] = "Вчера после состязания я слишком долго спал, а ночью замучила бессонница.",
    ["是你杀了他！"] = "Ты убил его!",
    ["是啊，时代的齿轮压过他们，听不到声音。"] = "Действительно, шестерни эпохи катятся по ним, и не слышно ни звука.",
    ["是委托我们寻人吗？有什么我可以帮忙的吗？"] = "Вы поручаете нам найти кого-то? Могу ли я чем-нибудь помочь?",
    ["是的。另一个就是刚刚救老罗德的<P_Yellow>亚瑟</>，他是“自杀”的幸存者，也是“自杀”案件变严重的标志。"] = "Да. Другой — <P_Yellow> Артур </>, который только что спас Старый Род. Он пережил попытку «самоубийства» и является признаком того, что случаи «самоубийства» становятся все более серьезными.",
    ["是的，就是那位让我呆坐两小时的警察先生。"] = "Да, именно тот полицейский, из-за которого я просидел сиднем два часа.",
    ["是的，当然。"] = "Да, конечно.",
    ["是的，谢谢您！"] = "Да, спасибо!",
    ["是的，这里是冥界的入口。"] = "Да, это вход в Подземный мир.",
    ["是的，那是我的一段人生。一段重要的人生。"] = "Да, это было частью моей жизни. Важная часть моей жизни.",
    ["是的，阅读信件时，我好像真的参加了一场婚礼。有白鸽、有鲜花、过去的朋友都在，我们也都在，所有人都在。"] = "Да, читая письмо, у меня возникло ощущение, будто я действительно присутствовал на свадьбе. Там были белые голуби, цветы, друзья из прошлого были все там, мы все были там, все были там.",
    ["是阿兹克先生您告诉我的，蜡烛是关键，所以我才想到用老师的蜡烛换掉永暗蜡烛。"] = "Это вы, господин Азик, сказали мне, что свеча является ключом, поэтому я подумал использовать свечи моего учителя вместо Свечи Вечной Тьмы.",
    ["暖场差不多了，挑战赛马上开始！"] = "Разминка почти закончилась, скоро начнется соревновательный матч!",
    ["暖场结束，欢迎参加第二届<P_Yellow>“破晓之时”</>挑战赛，比赛共三轮！"] = "Разминка окончена, добро пожаловать на второй матч-испытание <P_Yellow> «Час рассвета» </>, всего три раунда!",
    ["最先找到答案，离开“织梦黑匣”，就算赢得本轮比赛！"] = "Тот, кто первым найдет ответ и покинет «Черный ящик снов», побеждает в этом раунде конкурса!",
    ["最近很有名的那首诗？只抄了一半……难道不小心把草稿纸寄过来了？"] = "Это стихотворение, которое было очень популярно в последнее время? Он скопировал только половину... он случайно не прислал черновик?",
    ["有时候，大家抽空坐在一起，喝咖啡聊天，这就很好。"] = "Иногда так приятно просто выкроить время, посидеть всем вместе за чашечкой кофе и поговорить.",
    ["有请“启明小队”成员，迪文娜公布题目！"] = "Давайте поприветствуем члена «Отряда Рассвета», Дивину, объявившую эту тему!",
    ["有这么不像？"] = "Это настолько неузнаваемо?",
    ["有道理……我想试试。"] = "Это имеет смысл... Я хочу попробовать.",
    ["来吧，加入我们一起跳舞吧！"] = "Давай, присоединяйся к нам и танцуй!",
    ["来吧，来参加我的婚礼。鼓掌、吟诗、痛痛快快地道别。"] = "Приходи, приходи на мою свадьбу. Аплодируй, читай стихи и попрощайся от всей души.",
    ["杯子"] = "Чашка",
    ["柑橘"] = "Цитрусовые",
    ["根据手上这些线索，我或许可以推理出事情的真相……"] = "Основываясь на этих подсказках, я, возможно, смогу сделать вывод об истине...",
    ["梅林先生？您怎么来了？"] = "Мистер Мерлин? Почему ты здесь?",
    ["梦境捕手是凶猛的非凡生物，其他需要了解的，就是比赛的一部分了。为确保安全，比赛期间<P_Yellow>禁止离开学派</>。"] = "Ловец снов — свирепое существо из Потустороннего мира; все остальное, что вам нужно знать, является частью конкурса. В целях безопасности выход из школы во время соревнований запрещен <P_Yellow></>.",
    ["梦境捕手？"] = "Ловец снов?",
    ["死亡是永恒的宁静。我得到安宁，我的孩子们少一个累赘，这是划算的交易。"] = "Смерть — это вечный покой. Я обрету мир, а у моих детей станет одной обузой меньше. Это честная сделка.",
    ["每次送货时，他都喜欢大声地喊——这是“老师”让我送来的！"] = "Каждый раз, когда он доставлял товар, он любил громко кричать — это прислал мой «учитель»!",
    ["比如现在，你想聊聊去世的莎莉丝特小姐吗？"] = "Например, не хотели бы вы прямо сейчас поговорить о покойной Мисс Селесте?",
    ["比罗塞尔日记还残缺，是你点燃的小火<P_Yellow>花</>。"] = "Это еще более неполная, чем дневник Розеля, маленькая искра <P_Yellow>, которую вы зажгли </>.",
    ["比赛开场只需<P_Yellow>三秒</>，我会让你陷入深渊泥<P_Yellow>沼</>。"] = "Матч начнется всего через <P_Yellow>три секунды</>, я заставлю тебя упасть в пропасть <P_Yellow>болото</>.",
    ["比赛期间，我将拒绝回答一切相关提问！"] = "Во время состязания я отказываюсь отвечать на любые вопросы по теме!",
    ["气场呈现暗色，陌生的{{先生|女士}}，你因为什么而悲伤？"] = "Твоя аура кажется темной, странной, {{Mr.|Ms.}}, о чем ты грустишь?",
    ["气氛很热烈嘛，看来大家都热情高涨了，比赛马上开始！"] = "Атмосфера очень воодушевленная, кажется, все в приподнятом настроении, матч вот-вот начнется!",
    ["永暗的蜡烛，不毁的身躯，我将进入死亡的队列。"] = "Свеча вечной тьмы, тело нерушимое, Я пополню ряды мертвых.",
    ["永暗蜡烛需要亡魂封印，保持它的死亡温度。"] = "Свеча вечной тьмы требует запечатывания неупокоенных душ, чтобы поддерживать свою леденящую смертельную температуру.",
    ["求婚？"] = "Предложение?",
    ["求婚？！你没说要求婚……不许哭！我又没有拒绝你！"] = "Предложение?! Ты не говорил, что собираешься делать предложение... Не плачь! Я же тебе не отказала!",
    ["污染？“火种二号”是不是也能窃取污染？"] = "Искажение? Может ли «Огненное семя № 2» похитить порчу?",
    ["没事，他谨慎地做好了充分准备。"] = "Все в порядке, он предусмотрительно все подготовил.",
    ["没事，跟姐姐走。"] = "Все в порядке, пойдем с сестрой.",
    ["没什么事的话，我先走了。"] = "Если больше ничего не будет, я пойду.",
    ["没什么，只是记录一些开支。"] = "Ничего особенного, просто записываю некоторые расходы.",
    ["没关系！比赛一年才举办一次，就当是一次体验。"] = "Ничего страшного! Состязание проходит лишь раз в год, считай это просто новым опытом.",
    ["没反应，的确是普通的书。"] = "Никакого отклика... Похоже, обычная книга.",
    ["没喝完的牛奶？"] = "Недопитое молоко?",
    ["没有。"] = "Никто.",
    ["没有时间了……没有时间了……我是非凡者，我必须尝试新的仪式魔法……"] = "Времени нет... совсем нет времени... Я ведь Потусторонний, я должен попробовать новую ритуальную магию...",
    ["没有疑问了"] = "Больше никаких вопросов",
    ["没有，也许是接触神奇物品，被负面效果影响。"] = "Нет, возможно, она соприкоснулась с мистическим предметом и подверглась его негативному воздействию.",
    ["没有，我没有哭。姐姐说这是高兴的事，我不会哭的，我不是不懂事的小孩。"] = "Нет, я не плачу. Сестра сказала, что это счастье, я не буду плакать, я не невежественный ребенок.",
    ["没错。但我也想知道，他拿“心脏”去做什么？"] = "Это верно. Но я также хочу знать, что он собирается делать с «сердцем»?",
    ["没错，找到那本诡异的书，查清背后原因。"] = "Именно: найди ту зловещую книгу и выясни причину, что за этим стоит.",
    ["没问题！算我们临时组队比赛怎么样？"] = "Без проблем! Как насчет того, чтобы сформировать временную команду для соревнований?",
    ["没问题，也许你能有新发现。"] = "Нет проблем, возможно, вас ждут новые открытия.",
    ["活人不能在冥界待太久。主教肯定躲在这里，要先找到他。"] = "Живые не могут оставаться в Подземном мире слишком долго. Должно быть, здесь скрывается епископ; мы должны найти его первыми.",
    ["涂抹过的文字……难道是“曼哈尔鱼”？呕——"] = "Размазанный текст... может ли это быть «Рыба Манхар»? Фу-",
    ["涂鸦都清理了。我……有点不舒服。"] = "Все граффити стерты. Мне... немного не по себе.",
    ["渔网"] = "Рыболовная сеть",
    ["灵性预警！BATTLE 立刻停止！"] = "Духовное предупреждение! БИТВА: немедленно остановитесь!",
    ["熟悉的鱼腥味，但被牛奶冲淡了。"] = "Знакомый рыбный запах, но он разбавлен молоком.",
    ["爱德华极度焦虑，布雷尔畏惧黑暗，我无法忍受打开的门。"] = "Эдвард очень тревожится, Брел боится темноты, а я терпеть не могу открытую дверь.",
    ["爱德华的病症"] = "Симптомы Эдвардса",
    ["爸爸妈妈都消失了吗……"] = "Мама и папа тоже пропали...",
    ["狂乱，震慑，这只是观众的彩<P_Yellow>排</>。"] = "Безумие, Сдерживание, это всего лишь репетиции Зритель<P_Yellow></>.",
    ["玫瑰"] = "Роза",
    ["现在可以清除这些涂鸦了！"] = "Теперь я могу очистить эти каракули!",
    ["现在最重要的是找到<P_Yellow>亚瑟</>。艾琳，你先冷静。"] = "Самое главное сейчас — найти <P_Yellow> Артура </>. Ирен, сначала успокойся.",
    ["现在有两个关键人物，一个是蜡烛工坊的<P_Yellow>学徒芬恩</>，但他已经有一年多不做蜡烛了，而且，他的老师维斯塔也自杀了。"] = "Сейчас есть две ключевые фигуры. Один — <P_Yellow>Ученик Finn</> из свечной мастерской, но свечи он не делает уже больше года, а его учительница Веста тоже покончила жизнь самоубийством.",
    ["现在有请会长，贝尔纳黛女士，宣布比赛开始！"] = "А теперь давайте пригласим президента, госпожу Бернадетт, объявить о начале матча!",
    ["现在谁还用手工做的蜡烛啊，大工厂做的蜡烛又细腻又便宜，还没怪味。"] = "Кто в наше время пользуется самодельными свечами? Свечи с крупных фабрик и гладкие, и дешёвые, и никакого неприятного запаха.",
    ["现在，跟我来做些准备——带上封印物。"] = "А теперь пойдём со мной, чтобы сделать кое-какие приготовления — принеси Запечатанный Артефакт.",
    ["生命苦涩，而死亡永恒！"] = "Жизнь горька, но смерть вечна!",
    ["用于入场的空镜"] = "Пустое зеркало, используемое для входа",
    ["痛苦、悲伤的过往，都随着琴声飘散了。"] = "Болезненное, печальное прошлое унеслось прочь со звуком фортепиано.",
    ["的确有人存在偏见，但也有很多人相信你。"] = "Действительно, у некоторых людей есть предубеждения, но есть и те, кто верит в вас.",
    ["的确，又不能填饱肚子……去看看。"] = "Действительно, желудок ему тоже не набить... пойдем посмотрим.",
    ["直到最后，尼尔先生也没想过伤害任何人。"] = "До самого конца мистер Нил никогда не думал причинить кому-либо вред.",
    ["相爱的人们聚在一起，共赴一个春天。"] = "Люди, любящие друг друга, собрались вместе, чтобы отправиться к источнику.",
    ["看来“火种二号”也光荣牺牲了。"] = "Похоже, «Искра-2» тоже пала смертью храбрых.",
    ["看来还是韵脚押得不够多，我来试试三押！"] = "Кажется, рифм не хватает; позвольте мне попробовать тройную рифму!",
    ["真希望见到一个美满的……尼尔先生当年的物品还在吗？"] = "Я очень надеюсь увидеть счастливый конец... сохранились ли вещи мистера Нила того времени?",
    ["真的是阿兹克先生！不过……我也不算认识您。但我知道您之前是霍伊大学的教员，有一个学生叫克莱恩·莫雷蒂。"] = "Это действительно господин Азик! Хотя... Я тебя особо не знаю. Но я знаю, что раньше вы были преподавателем в Университете Хой и у вас был студент по имени Клейн Моретти.",
    ["确实需要你的帮助。"] = "Мне нужна твоя помощь.",
    ["祂、祂是……隐匿贤者！"] = "Он, Он... Скрытый Мудрец!",
    ["祂？祂是谁？"] = "Ему? Кто он?",
    ["祝您顺利，警察先生。"] = "Желаю вам всего наилучшего, офицер.",
    ["祝贺你！今天是“破晓之时”最后一轮了。"] = "Поздравляем! Сегодня последний тур «Часа рассвета».",
    ["神父看到他上了去<P_Yellow>拉姆德古堡</>的火车，一个月才赚3镑的家伙，怎么舍得去度假胜地？！女神啊，他到底偷了我的什么啊？"] = "Священник видел, как он садился в поезд до <P_Yellow>Ламуд Castle</>. Как мог парень, который зарабатывает всего 3 фунта в месяц, позволить себе поехать на курорт?! О Богиня, что же он украл у меня?",
    ["空"] = "Пустой",
    ["空镜"] = "Пустое зеркало",
    ["窃取污染？这可能导致他当场死亡！"] = "Воровство Искажения? Это может привести к тому, что он умрет на месте!",
    ["站住！你这个狂妄的小偷！"] = "Остановитесь здесь! Ты высокомерный вор!",
    ["竟然用笔记本，掉包应该归还的书！"] = "На самом деле использовать блокнот, чтобы заменить книгу, которую следовало вернуть!",
    ["笔记本可以给我吗？我也许能找到他。"] = "Можешь дать мне блокнот? Возможно, я смогу его найти.",
    ["笨蛋……这简直是奇迹！"] = "Идиот... это просто чудо!",
    ["第一轮比赛，我们在梦中相遇，这说明梦境是相连的！"] = "В первом туре конкурса мы встретились во сне, а значит, мечты связаны!",
    ["第二天……"] = "На следующий день...",
    ["第二天，我想去预支下个月的薪水，看到老板在用牛排喂它的狗。我上前想跟老板说话，老板的狗却以为我要抢它的牛排，把我咬了……"] = "На следующий день я хотел попросить аванс в счет зарплаты за следующий месяц и увидел, как мой босс кормит свою собаку стейком. Я подошел поговорить с ним, но собака подумала, что я пытаюсь украсть ее стейк, и укусила меня...",
    ["等一下……帕里克，太危险了……"] = "Подожди... Парик, это слишком опасно...",
    ["等一下，让我试试。"] = "Подожди минутку, дай мне попробовать.",
    ["等姐姐得到永暗蜡烛的垂怜，姐姐就带你去见爸爸妈妈。"] = "Вот заслужит сестричка милость Свечи Вечной Тьмы, и сестричка отведет тебя к папе с мамой.",
    ["等等！你的信还在我这里。"] = "Постой! Твоё письмо всё ещё у меня.",
    ["等等，{{PlayerName}}！"] = "Подожди, {{PlayerName}}!",
    ["等等，你怎么突然要谢谢我？"] = "Подожди, а почему ты вдруг меня благодаришь?",
    ["算了，尼尔，算了，迟到两次也太过分了，莎莉丝特小姐已经足够礼貌了，你要反省。"] = "Забудь об этом, Нил, забудь об этом. Опоздать дважды – это уже слишком. Мисс Селеста была достаточно вежлива; вам нужно задуматься о себе.",
    ["算了，我还是去排队吧"] = "Забудь об этом, вместо этого я пойду в очередь",
    ["米贝拉，怎么能因为一个人的途径，而怀疑他的品格？"] = "Ребекка, как ты можешь сомневаться в чьем-то характере только из-за его Пути?",
    ["组队？帕里克竟然跟别人组队？"] = "Команда? Парик действительно с кем-то объединился?",
    ["结束观察"] = "Окончание наблюдения",
    ["结果，哈哈那老太婆卖的都是臭鸡蛋！艾琳一晚上都在挑还能吃的鸡蛋……"] = "Как оказалось, хаха, эта старушка продавала тухлые яйца! Ирэн провела всю ночь, выбирая те, что еще были съедобны...",
    ["绝对不行，这会让使用者当场死亡！"] = "Абсолютно нет, это приведет к тому, что пользователь умрет на месте!",
    ["继续调查菲丽丝的事？"] = "Продолжить расследование дела Филлис?",
    ["维斯塔……这个名字好熟悉……"] = "Виста... Это имя звучит так знакомо...",
    ["美味！请进！请进！"] = "Вкусный! Пожалуйста, введите! Пожалуйста, введите!",
    ["老师比我聪明得多，他早就预感到了蜡烛工坊的倒闭，提前把我送进了糖厂学手艺。"] = "Мой учитель был намного умнее меня. Он давно предчувствовал закрытие свечного цеха и отправил меня на сахарный завод заранее обучиться ремеслу.",
    ["老师生前发现集市上除了工厂的便宜蜡烛，还出现了一种点不着的蜡烛。"] = "Перед смертью мой учитель обнаружил, что помимо дешевых фабричных свечей на рынке появились свечи, которые не загорались.",
    ["老师追查那些蜡烛，最后发现是有人举办诡异的<P_Yellow>“死亡”庆典</>，在庆典上分发了这些蜡烛。"] = "Учитель выслеживал происхождение тех свечей и выяснил, что кто-то устроил жуткое <P_Yellow>празднество «Смерти»</>, где и раздавал их.",
    ["老板，您知道最近总有人自杀的事吗？"] = "Босс, вы знаете о недавних самоубийствах?",
    ["老维斯塔临死前，给这条街上的店，送了好些蜡烛。大半个月了，我还没用完呢。"] = "Прежде чем умер старый Виста, он подарил много свечей магазинам на этой улице. Прошло уже больше полумесяца, а я еще не закончил ими пользоваться.",
    ["老罗德经常来蜡烛工坊，找老师聊天。老师死后，他就没人说话了……"] = "Старый Род часто приходил в свечную мастерскую, чтобы пообщаться с моим учителем. После смерти учителя ему не с кем было поговорить...",
    ["老罗德迷糊了，举着蜡烛说要回归死亡！我喊不住他！"] = "Старый Род в замешательстве; он держит свечу и говорит, что хочет вернуться к смерти! Я не могу остановить его!",
    ["老罗德，你醒醒。"] = "Старина Род, очнись.",
    ["老鼠到底是怎么回事？"] = "Что происходит с мышами?",
    ["考虑我的建议吗？我们临时组队，战利品共有？"] = "Обдумываете мое предложение? Сформируем временную команду и поделим добычу?",
    ["而且按照规则，只要有一个人代表小队报名即可。"] = "А по правилам, если от имени команды зарегистрируется один человек, это засчитывается.",
    ["而我也该走向我的春天，继续我的相会与离别了。"] = "И мне тоже пора идти к своей весне, к продолжению встреч и расставаний.",
    ["聊聊照片中的少女"] = "Поговорить о девушке на фото",
    ["聊聊面具"] = "Поговорим о маске",
    ["胜出者将赢得“破晓勋章”，加入<P_Yellow>“启明小队”</>，直面机密案件。"] = "Победитель получит «Медаль Рассвета» и присоединится к <P_Yellow>«Отряду Утренней Звезды»</>, чтобы расследовать засекреченные дела.",
    ["能有你这样的学生，他会骄傲的。"] = "Он бы гордился, если бы у него был такой ученик, как ты.",
    ["自杀者的亡魂很可能残缺，我想来为他们祷告，给他们带来安宁。"] = "Души тех, кто совершает самоубийство, вероятно, несовершенны. Я хочу прийти и помолиться за них, чтобы они принесли им мир.",
    ["自称是猎人却总被猎物反<P_Yellow>杀</>——"] = "Заявляющий, что он охотник, но всегда противодействующий <P_Yellow>, убитый </> добычей —",
    ["艾琳？艾琳花钱找我？我前天出门前还跟她吵了架……我以为她暂时不想见到我呢。"] = "Ирен? Ирен потратила деньги, чтобы найти меня? Я поспорил с ней позавчера перед отъездом... Я думал, она какое-то время не хочет меня видеть.",
    ["芬恩他们背着老罗德离开了……"] = "Финн и остальные унесли старого Рода...",
    ["芬恩！"] = "Финн!",
    ["芬恩，你们先把老罗德送到诊所，这里交给我们。"] = "Финн, сначала отвези Старого Рода в клинику; оставьте это место нам.",
    ["芬恩，你要做蜡烛吗？"] = "Финн, хочешь сделать свечу?",
    ["芬恩，你还好吗？"] = "Финн, ты в порядке?",
    ["芬恩，动手啊！你是第九个，九是多么特殊的数字你明白吧？"] = "Финн, действуй же! Ты девятый, ты же понимаешь, насколько это особое число?!",
    ["芬恩，是刚刚那个青年？"] = "Финн, это тот молодой человек, который только что был?",
    ["芬恩，等等！"] = "Финн, подожди!",
    ["茉莉"] = "Жасмин",
    ["茉莉花香？这根本不是我喜欢的气味！"] = "Аромат жасмина? Мне этот запах совсем не по душе!",
    ["莎莉丝特小姐很了解钢琴……哦，温蒂夫人说过，她是一名调音师。"] = "Мисс Селеста знает толк в пианино... ох, миссис Венди сказала, что она настройщик фортепиано.",
    ["莎莉丝特小姐，我为我刚才的固执道歉。"] = "Мисс Селеста, я сейчас прошу прощения за свое упрямство.",
    ["莎莉丝特小姐，真的因为疾病……"] = "Мисс Селеста, она действительно умерла от болезни...",
    ["莎莉丝特小姐？"] = "Мисс Селеста?",
    ["莎莉丝特小姐？您怎么在……糟糕！难怪总觉得忘记了什么……"] = "Мисс Селеста? Почему ты... О нет! Неудивительно, что мне показалось, что я что-то забыл...",
    ["莎莉丝特！"] = "Селеста!",
    ["莎莉！"] = "Салли!",
    ["莎莉！不好了！"] = "Салли! О, нет!",
    ["菲丽丝之前在廷根做<P_Yellow>心理医生</>，是我们的骄傲！"] = "Филлис раньше работала психологом <P_Yellow></> в Тингене; она наша гордость!",
    ["菲丽丝对我们进行<P_Yellow>催眠</>，这是她在廷根学到的！"] = "Филлис применила к нам <P_Yellow>Гипноз</>; вот чему она научилась в Тингене!",
    ["菲丽丝沉睡前，发生过什么事吗？"] = "Что-нибудь произошло до того, как Филлис заснула?",
    ["菲丽丝的沉睡症，也和那次<P_Yellow>催眠</>有关？"] = "Сонная болезнь Филлис также связана с этим <P_Yellow>Гипноз</>?",
    ["蒙特利留下的面具"] = "Маска, оставленная Монтереем",
    ["虽然这次自杀的事件有封印物的诱导，但村民的痛苦是真实的。"] = "Хотя этот инцидент с самоубийством был вызван Запечатанным Артефактом, боль жителей деревни реальна.",
    ["蜡烛是核心线索，如果能查出受害者<P_Yellow>获得蜡烛的渠道</>，就能追查到幕后之人。"] = "Свеча является основной подсказкой. Если мы сможем выяснить канал, через который жертва <P_Yellow> получила свечу </>, мы сможем выследить человека, стоящего за ней.",
    ["蜡烛？"] = "Свечи?",
    ["蠢鱼偏爱重金<P_Yellow>属</>，要认罗塞尔做教<P_Yellow>父</>？"] = "Глупая рыба предпочитает тяжёлые метал<P_Yellow>лы</>, желая признать Розеля крёстным от<P_Yellow>цом</>?",
    ["血水？快，把门撞开！西奥多！"] = "Кровь? Быстро, выломайте дверь! Теодор!",
    ["表达歉意，也是一个绅士应该做的。没错，这不算打扰，莎莉丝特小姐会理解的。"] = "Выражение извинений – это то, что должен сделать джентльмен. Да, это не считается ее беспокойством. Мисс Селеста поймет.",
    ["西奥多……好像没事了？"] = "Теодор... кажется, с ним всё в порядке?",
    ["西奥多……我们有段时间没见了。"] = "Теодор... давненько мы не виделись.",
    ["西奥多……是不是有救了……"] = "Теодор... Неужели он спасен...",
    ["西奥多好像没什么大问题……"] = "У Теодора, похоже, нет никаких серьезных проблем...",
    ["西奥多没有恶意，他只是想活着……"] = "У Теодора нет злого умысла, он просто хочет жить...",
    ["西奥多！你在吗？"] = "Теодор! Ты здесь?",
    ["西奥多，你为什么抓老鼠？"] = "Теодор, почему ты ловишь мышей?",
    ["西奥多，笼子又抓到老鼠了！"] = "Теодор, клетка поймала еще одну мышь!",
    ["西奥多？他一定遇上麻烦了，才会想到偷书！"] = "Теодор? Должно быть, ему пришлось столкнуться с неприятностями, когда он подумал о краже книги!",
    ["西奥多？！得阻止他！"] = "Теодор?! Должен остановить его!",
    ["要不你带他们去找西奥多，拿回那本书？"] = "Почему бы тебе не взять их с собой, чтобы найти Теодора и вернуть книгу?",
    ["要不送一个小礼物吧，向莎莉丝特小姐表示歉意？算了，算了……"] = "Почему бы тебе не сделать мне небольшой подарок в качестве извинения перед мисс Салистер? Забудь, забудь...",
    ["要是在冥界真的遇到老师，他肯定骂我，呵呵，肯定说我还没活到他的岁数，怎么就能死呢！"] = "Если бы я действительно встретил своего учителя в Подземном мире, он бы меня обязательно отругал. Хе-хе, он бы точно сказал, что я еще даже не дожил до его возраста, так как же я мог умереть!",
    ["观众途径有催眠能力，她成为非凡者了？"] = "Зритель канала обладает способностью гипнотизировать, стала ли она неординарной личностью?",
    ["观察"] = "Осмотреть",
    ["警察不需要替罪犯的行为道歉。"] = "Полиции не нужно извиняться за действия преступника.",
    ["警察先生，你该不会不知道，求婚在人生中有多重要吧？"] = "Офицер, вы ведь понимаете, насколько важно в жизни человека предложение руки и сердца?",
    ["警察办案，这个人是惯偷！"] = "Полиция работает! Этот человек — вор-рецидивист!",
    ["询问兄妹断联的原因"] = "Спросить о причине разрыва связи между братом и сестрой",
    ["该不会觉得我不守信用吧？"] = "Подумает ли она, что я ненадежен?",
    ["说出想法"] = "Высказать мысли",
    ["说唱可是学派“旧日复兴乐团”里最火的艺术形式之一！"] = "Рэп — одна из самых популярных форм искусства в школе «Great Old One Revival Orchestra»!",
    ["请一定告诉阿兹克先生，午夜，墓地广场。"] = "Пожалуйста, обязательно скажите господину Азику: полночь, кладбищенская площадь.",
    ["请大家不要担心，我已经让夫人喝下了药水，她稍后就会醒来。"] = "Пожалуйста, не волнуйтесь, все. Я уже велел даме выпить зелье; она скоро проснется.",
    ["请开始吧"] = "Пожалуйста, начните",
    ["请您告诉阿兹克先生，今天<P_Yellow>午夜</>，就是<P_Yellow>庆典</>的日子。"] = "Пожалуйста, сообщите г-ну Азику, что сегодня в полночь <P_Yellow> </> - день празднования <P_Yellow> </>.",
    ["请求拿到剧本"] = "Запросить сценарий",
    ["请等等我，我去拿书。"] = "Пожалуйста, подождите меня, я принесу книгу.",
    ["读心？狂乱？或者用心理暗示找人单<P_Yellow>挑</>？"] = "Чтение мыслей? Безумие? Или использовать «Психологическое внушение», чтобы вызвать кого-нибудь на дуэль<P_Yellow></>?",
    ["谢谢。"] = "Спасибо.",
    ["谢谢你们，丽贝卡，佐伊学姐。"] = "Спасибо, Ребекка, старшая Зоя.",
    ["谢谢你，我的头不那么疼了。真倒霉，怎么死了还会疼。"] = "Спасибо, голова уже не так болит. Как не повезло, как после смерти все еще может болеть.",
    ["谢谢你，阿兹克先生。"] = "Спасибо, господин Азик.",
    ["谢谢，您怎么会在这里？"] = "Спасибо. Почему ты здесь?",
    ["贝尔纳黛挥舞手臂，半透明的“破晓勋章”像烟花一样绽放开来，散成无数小星星落向四方。\n学派的天花板上浮现了许多闪烁的星星。\n学员纷纷欢呼鼓掌，跃跃欲试。"] = "Бернадетт взмахнула рукой, и полупрозрачный «Орден рассвета» рассыпался фейерверком, падая во все стороны бесчисленными искорками-звездами.\nНа потолке школы проступило множество мерцающих звезд.\nУченики восторженно захлопали, горя нетерпением.",
    ["贝尔纳黛！会长！"] = "Бернадетт! Президент!",
    ["赌你全部金镑，我的赢面比永恒烈阳更耀<P_Yellow>眼</>！"] = "Держу пари на все ваши золотые фунты, что мои шансы на победу выше, чем у Вечно Пылающее Солнце<P_Yellow></>!",
    ["走吧！"] = "Идем!",
    ["身旁的学员们陆续结队，完成了报名。"] = "Студенты рядом с ними одна за другой сформировали группы и завершили регистрацию.",
    ["输掉的人，去五月庄园给怪物当一个月陪<P_Yellow>练</>。"] = "Проигравший отправляется в Мэй-Мэнор, чтобы в течение месяца служить спарринг-партнером монстров <P_Yellow></>.",
    ["还不确定"] = "Пока не уверен",
    ["还好，还好，你要拿去送人吗？难道……是女孩子？"] = "Неплохо, вполне неплохо. Собираешься кому-то подарить? Неужели... девушке?",
    ["还寄来一个丑木雕？"] = "И ты прислал уродливую резьбу по дереву?",
    ["还是上次那位？"] = "Тот же самый, что и в прошлый раз?",
    ["还有呼吸，老罗德只是失血昏迷了。"] = "Он все еще дышит; Старый Род просто оглушен от потери крови.",
    ["还没等你问清楚，芬恩就急匆匆地跑开了。\n他跑得太急，没跑几步就撞在了别人身上，连忙道歉，低头跑开了。"] = "Прежде чем ты успел спросить, Финн поспешил прочь. \n Он бежал слишком быстро и врезался в кого-то, не успев сделать несколько шагов. Он быстро извинился, опустил голову и убежал.",
    ["还说要给你介绍一位新的相亲对象……谁能预料，会有人当街行凶？警局换了好几队警员跟进，都没能抓住凶手。"] = "Он даже сказал, что собирается познакомить тебя с новым поклонником... кто мог предсказать, что кто-то совершит убийство на улице? Полицейский участок направил на поиски несколько групп, но им не удалось поймать убийцу.",
    ["这个仪式也是布兰登教你的？"] = "Брэндон тоже научил тебя этому ритуалу?",
    ["这个吝啬老头，什么都想报销，单据积累了一沓，哪里都放不下。"] = "Этот скупой старик хочет, чтобы ему все возместили, квитанции скопились в стопку, а девать их некуда.",
    ["这个幕后的凶手，不仅盗取了我孩子的墓葬，还扭曲了这些村民对死亡的想象。"] = "Вдохновитель, стоящий за этим, не только украл могилу моего ребенка, но и исказил представление жителей о смерти.",
    ["这么厚一沓报销单，都是尼尔先生的？"] = "Такая толстая стопка бланков возмещения, все они принадлежат мистеру Нилу?",
    ["这些报销单怎么会在外面？"] = "Почему эти формы возмещения находятся снаружи?",
    ["这件封印物，是给帕里克的。"] = "Этот запечатанный артефакт предназначен для Парика.",
    ["这几个月，已经发生了十四起这样的“自杀”案件了，自杀现场都有<P_Yellow>蜡烛</>。"] = "За последние несколько месяцев таких случаев «самоубийств» уже было четырнадцать, и на каждом месте самоубийства были свечи <P_Yellow></>.",
    ["这又不是什么稀奇事，你也想自杀？先喝两杯，喝完了还想死，就回家跟你老妈聊聊。"] = "В этом нет ничего редкого. Ты тоже хочешь покончить жизнь самоубийством? Сначала выпейте пару напитков. Если вы все еще хотите умереть после того, как закончите, идите домой и поговорите со своей матерью.",
    ["这场仪式应该是临时组织的，为什么突然要献祭这么多人？"] = "Этот ритуал, должно быть, был организован на ходу, с чего вдруг приносить в жертву столько людей?",
    ["这小贼身上没有永暗蜡烛的气息，放他走吧。"] = "На этом маленьком воришке нет ауры Свечи Вечной Тьмы. Отпусти его.",
    ["这就是——“浸泡曼哈尔鱼眼珠的牛奶”？"] = "Это «Молоко, пропитанное глазными яблоками манхарской рыбы»?",
    ["这才是真正的封印物“破晓号”。"] = "Это настоящий Запечатанный Артефакт «Рассвет».",
    ["这既是对非凡能力的考察，也是对智慧和勇气的检验。"] = "Это одновременно проверка способностей Потустороннего и проверка мудрости и смелости.",
    ["这是上次做木雕剩下的木块？钢琴也是木头做的……"] = "Это кусок дерева, оставшийся от последней резьбы по дереву? Пианино тоже делается из дерева.",
    ["这是失踪者们的资料。工人们收入微薄，没有留下照片，这里只有他们的基本信息。"] = "Это дела пропавших без вести. Рабочие имеют мизерные доходы и не оставили фотографий; здесь только их основная информация.",
    ["这样才算“准备充分”，出发吧。"] = "Вот теперь подготовка действительно завершена. Выдвигаемся.",
    ["这样的仪式会引来邪恶和危险！"] = "Такой ритуал привлечет зло и опасность!",
    ["这根蜡烛需要大量亡魂的封印，我的儿子在战场上，满足这样的条件。而这个托马斯神父……想人为制造大量亡魂。"] = "Эта свеча требует запечатывания многих душ. Мой сын был на поле боя, что соответствовало условиям. И этот отец Томас... хочет искусственно создать большое количество душ.",
    ["这次醒来多亏了克莱恩的信，让我回想起了很多。"] = "На этот раз я пробудился благодаря письму Клейна — оно помогло мне многое вспомнить.",
    ["这里就是拉姆德小镇……风景如画，不愧是廷根人的度假首选。"] = "Это Ламуд... живописный, достойный того, чтобы стать лучшим выбором для отдыха жителей Тингена.",
    ["这里手工业很发达，我准备去廷根联系一些老朋友，帮手工作坊找点出路。"] = "Здесь прекрасно развиты ремёсла, и я собираюсь наведаться в Тинген к старым друзьям, чтобы помочь местным мастерским найти рынок сбыта.",
    ["这里是<P_Yellow>科诺桑小镇</>？"] = "Это <P_Yellow>городок Коносан</>?",
    ["进入“织梦黑匣”"] = "Войдите в «Черный ящик снов»",
    ["追上去"] = "Догнать",
    ["送什么好呢？我还算擅长木雕……她会喜欢木雕吗？"] = "Что же подарить? Я неплохо режу по дереву... Понравится ли ей деревянная фигурка?",
    ["道歉"] = "Извиняться",
    ["邀请丽贝卡"] = "Пригласить Ребекку",
    ["邀请罗珊"] = "Пригласить Розанну",
    ["那“火种”呢？被偷走了？"] = "А «Искра»? Ее украли?",
    ["那不是你的错，你被蜡烛引诱了。"] = "В этом нет твоей вины, тебя совратила свеча.",
    ["那个人并没有在意，反而露出了关切的神情。\n这是一张你熟悉的面孔——黑夜教会的托马斯神父。"] = "Собеседник ничуть не рассердился, на его лице отразилось искреннее сочувствие.\nПеред вами было знакомое лицо — отец Томас из Церкви Богини Вечной Ночи.",
    ["那个孩子，喜欢格斗，总是拖着一把阔剑跑来跑去，说想成为骑士。"] = "Этот ребенок любил драться, всегда таскал с собой палаш и говорил, что хочет стать рыцарем.",
    ["那么多工厂，维斯塔选择送你去糖厂。明亮，温暖，甜蜜的东西才是生活的意义，也许这是他教你的最后一课。"] = "Из всех заводов Виста предпочла отправить вас на сахарный завод. Яркие, теплые, милые вещи – смысл жизни; возможно, это был последний урок, который он преподал тебе.",
    ["那位主教……你们认识他多久了？"] = "Этот епископ... как долго вы его знаете?",
    ["那你打我干什么?奇了怪了，难道是出于正义？"] = "Тогда почему ты меня ударил? How strange, was it out of justice?",
    ["那倒霉的蜡烛！是教会<P_Yellow>济贫</>发的，我特意多抢了两根，结果根本点不着。"] = "Эта несчастная свеча! Он был распространен церковью для помощи бедным <P_Yellow> </>. Я специально взял два дополнительных, но они вообще не горели.",
    ["那刚才怎么回事？你遇到麻烦了？"] = "Тогда о чем это было только что? У тебя проблемы?",
    ["那就……再做一个梦！{{PlayerName}}，你真是个天才！"] = "Тогда... давай помечтаем еще раз! {{PlayerName}}, ты действительно гений!",
    ["那就开始散步吧。"] = "Тогда начнем нашу прогулку.",
    ["那年春天来临前，他们即将订婚，一场猛烈的肺病却将她带去了女神的神国。"] = "Еще до наступления весны того года они собирались обручиться, но тяжелая болезнь легких привела ее в царство Богини.",
    ["那怎么还闷闷不乐？"] = "Тогда почему ты все еще такой мрачный?",
    ["那托马斯神父的真正目的是什么……"] = "Какова же тогда истинная цель отца Томаса?..",
    ["那春天呢？"] = "А что насчет весны?",
    ["那是一个本该美好，却戛然而止的故事……他们后来……"] = "Это была история, которая должна была быть красивой, но она внезапно закончилась... что же случилось с ними потом...",
    ["那是为我儿子制作的。他长眠在拉姆德古堡——“<P_Yellow>初代拉姆德男爵的长子，一位骑士，一位真正的勇者</>”……"] = "Это было сделано для моего сына. Он покоится в замке Ламуд — «<P_Yellow>старший сын первого барона Ламуда, рыцарь и истинный герой</>»...",
    ["那样的老师，是绝不会想自杀的。"] = "Такой учитель никогда бы не захотел покончить жизнь самоубийством.",
    ["那现在怎么办？"] = "Что нам делать сейчас?",
    ["酒吧里有狗拿耗子比赛，我想卖点钱。"] = "В баре конкурс по ловле крыс, я хочу подзаработать.",
    ["钢琴。"] = "Фортепиано.",
    ["钢琴？！"] = "Фортепиано? !",
    ["阿兹克先生——！"] = "Господин Азик!",
    ["阿兹克先生，你在担心什么吗？"] = "Господин Азик, вы чем-то обеспокоены?",
    ["阿兹克先生，芬恩让我告诉你，“庆典”今晚会在墓地广场举行。"] = "Господин Азик, Финн просил меня передать вам, что «праздник» пройдет сегодня вечером на кладбищенской площади.",
    ["阿兹克先生，这里就是……冥界吗？"] = "Мистер Азик, это и есть... подземный мир?",
    ["阿兹克先生？"] = "Господин Азик?",
    ["除了封印物，你们还需要一点奇迹。"] = "Помимо Запечатанного Артефакта, вам также нужно немного надежды.",
    ["随后，舞蹈的人群牵着手将你围住，你加入了他们，一同欢快地跳起舞来。"] = "Затем танцующая толпа взялась за руки и окружила вас, и вы присоединились к ним, счастливо танцуя вместе.",
    ["隐匿贤者？那个灌输知识的邪神！"] = "Скрытый мудрец? Этот злой бог, который вселяет знания!",
    ["难道你想要焦香人设永不<P_Yellow>倒</>？"] = "Вы хотите, чтобы ваша обугленная личность никогда не упала <P_Yellow></>?",
    ["难道有其他受害者？"] = "Могут ли быть еще жертвы?",
    ["餐厅里存在随时可能作案的窃贼，你却只关心钢琴？"] = "В ресторане вор, который может напасть в любой момент, а тебя волнует только пианино?",
    ["麻烦您伸出右手。"] = "Пожалуйста, протяните правую руку.",
    ["黑店！退钱，我们要退钱！"] = "Магазин грабежей! Возврат денег, мы хотим вернуть деньги!",
    ["黑板上的裂痕越来越多，终于彻底碎裂。布兰登向学生走去，而他和学生们的轮廓正逐渐消散。\n布兰登：这里必须有一所学校，必须有人点亮通往未来的那盏灯……"] = "Трещин на классной доске становилось всё больше, пока она окончательно не раскололась вдребезги. Брэндон пошёл к ученикам, и его силуэт вместе с силуэтами детей стал постепенно растворяться.\nБрэндон: Здесь непременно должна быть школа... Кто-то должен зажечь светильник, ведущий в будущее...",
    ["黑板里依次冒出点点星光，组成模糊的人形——伊西多、乔伊斯、帕特里克的模糊轮廓坐在地上，听老师讲这最后一课。\n布兰登在黑板上的书写变得越来越有力，腰板也逐渐挺直，仿佛回到了在那个被阳光笼罩的小院子里，给孩子们讲课的日子。"] = "Из классной доски одна за другой проступили звездные искры, складываясь в смутные человеческие силуэты: размытые очертания Исидора, Джойса и Патрика сидели на полу, внимая последнему уроку учителя.\nПочерк Брэндона на доске становился все тверже, спина выпрямлялась, словно он вернулся в те дни, когда вел уроки для детей в залитом солнцем маленьком дворике.",
}
